import XCTest
@testable import Screener

/// Client→server builders against `messages.json` / `clipboard.json`
/// (generated by calling the reference; see Tools/fixtures/README.md).
/// Each test uses exactly the `args` the fixture script passed.
final class MessagesTests: XCTestCase {
    private var f: [String: Any] = [:]

    override func setUpWithError() throws { f = try Fixture.load("messages") }

    private func result(_ key: String) -> String { (f[key] as! [String: Any])["result"] as! String }

    // MARK: messages.json — one assertion per fixture key

    func testAppleViewerCommandMask() {
        XCTAssertEqual(ClientMessage.appleViewerCommandMask.hex, result("_build_apple_viewer_command_mask"))
    }

    func testEncryptedPointerEvent() throws {
        // args: buttons=1, cbc_key=aa×16, x=100, y=200
        let msg = try ClientMessage.encryptedPointerEvent(key: Data(hex: "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
                                                          buttons: 1, x: 100, y: 200)
        XCTAssertEqual(msg.hex, result("_build_msg10_pointer"))
    }

    func testAutoFramebufferUpdate() {
        XCTAssertEqual(ClientMessage.autoFramebufferUpdate(w: 2752, h: 2064).hex, result("build_auto_framebuffer_update"))
    }

    func testFramebufferUpdateRequest() {
        XCTAssertEqual(ClientMessage.framebufferUpdateRequest(incremental: false).hex, result("build_fbu_request"))
    }

    func testKeyEvent() {
        XCTAssertEqual(ClientMessage.keyEvent(down: true, keysym: 97).hex, result("build_key_event"))
    }

    func testPointerEvent() {
        XCTAssertEqual(ClientMessage.pointerEvent(buttons: 1, x: 100, y: 200).hex, result("build_pointer_event"))
    }

    func testSetEncryptionCommand2() {
        // build_post_encryption_toggle == RFC §5.6 command=2 short form
        XCTAssertEqual(ClientMessage.setEncryption(command: .stop).hex, result("build_post_encryption_toggle"))
    }

    func testSetEncodings() {
        XCTAssertEqual(ClientMessage.setEncodings().hex, result("build_set_encodings"))
    }

    func testViewerInfo() {
        let args = (f["build_viewer_info"] as! [String: Any])["args"] as! [String: Any]
        let mask = Data(hex: args["command_mask"] as! String)
        XCTAssertEqual(ClientMessage.viewerInfo(commandMask: mask).hex, result("build_viewer_info"))
    }

    func testSetDisplayConfiguration() {
        // args: width=1376, height=1032 (logical), hidpi_scale=2.0; reference
        // default display_name.
        let msg = ClientMessage.setDisplayConfiguration(logicalWidth: 1376, logicalHeight: 1032, hidpiScale: 2.0,
                                                        displayName: "iShareScreen Virtual Display")
        XCTAssertEqual(msg.hex, result("build_virtual_display"))
        XCTAssertEqual(msg.count, 308, "RFC §7.1: 1 display, 5 modes = 308 bytes")
    }

    /// RFC §7.3 / §10.9 step 1: the mid-session resize request is the full
    /// dynamic descriptor, byte-identical to what session.send_dynamic_resolution
    /// sends (rfb.build_virtual_display) for the same size, scale and the
    /// reference's 3840×2160 max (ours defaults to 3840×3840, see below).
    func testDynamicResizeDescriptorMatchesTheReference() throws {
        let entry = f["build_virtual_display_dynamic_resize"] as! [String: Any]
        let cases = (entry["args"] as! [String: Any])["cases"] as! [[String: Any]]
        let results = entry["result"] as! [String]
        XCTAssertEqual(cases.count, results.count)
        for (c, expected) in zip(cases, results) {
            let w = c["width"] as! Int, h = c["height"] as! Int, scale = c["hidpi_scale"] as! Double
            let msg = ClientMessage.setDisplayConfiguration(logicalWidth: w, logicalHeight: h, hidpiScale: scale,
                                                            dynamic: true, displayName: "iShareScreen Virtual Display",
                                                            maxWidth: 3840, maxHeight: 2160)
            XCTAssertEqual(msg.hex, expected, "\(w)x\(h)@\(scale)")
            let d = 0x0c
            XCTAssertEqual(Data(msg[d + 0x7a..<d + 0x82]).hex, "0000000100000004", "display_flags bit 0, display_type 4")
            XCTAssertEqual(Data(msg[d + 0x92..<d + 0x9a]).hex, "0000000000000007", "mode indices 0, rotations 7")
        }
        // What requestDisplay sends: the same bytes but for the max size field.
        let g = DisplayGeometry(logicalWidth: 1032, logicalHeight: 1376, hidpiScale: 2)
        let ours = ClientMessage.setDisplayConfiguration(logicalWidth: 1032, logicalHeight: 1376, hidpiScale: 2,
                                                         dynamic: true, displayName: "iShareScreen Virtual Display",
                                                         maxWidth: g.maxBacking.width, maxHeight: g.maxBacking.height)
        let reference = Data(hex: results[0])
        XCTAssertEqual(Data(ours[0x0c + 0x8a..<0x0c + 0x92]).hex, "00000f0000000f00", "max 3840x3840")
        var patched = ours
        patched.replaceSubrange(0x0c + 0x8e..<0x0c + 0x92, with: [0, 0, 0x08, 0x70])   // 2160
        XCTAssertEqual(patched, reference)
    }

    func testFixtureKeysAllCovered() {
        // Guard: if the fixture grows a key, this test forces a matching assertion.
        let covered: Set<String> = ["_build_apple_viewer_command_mask", "_build_msg10_pointer",
                                    "build_auto_framebuffer_update", "build_fbu_request", "build_key_event",
                                    "build_pointer_event", "build_post_encryption_toggle", "build_set_encodings",
                                    "build_viewer_info", "build_virtual_display",
                                    "build_virtual_display_dynamic_resize",
                                    "parse_apple_display_layout" /* ServerMessagesTests */]
        XCTAssertEqual(Set(f.keys), covered)
    }

    // MARK: clipboard.json (trivial control messages only; 0x1f send is Task 17)

    func testClipboardFetchAndAutoPasteboard() throws {
        let c = try Fixture.load("clipboard")
        XCTAssertEqual(ClientMessage.clipboardFetch().hex, c["build_clipboard_request"] as! String)
        XCTAssertEqual(ClientMessage.autoPasteboard(selector: 1).hex, c["build_auto_pasteboard_msg"] as! String)
    }

    // MARK: RFC byte forms (no reference builder / fixture)

    func testSetEncryptionCommand1MatchesRFC() {
        // RFC §5.6 full form == apple.APPLE_0X12_FOLLOWUP
        XCTAssertEqual(ClientMessage.setEncryption(command: .start).hex, "120000010001000100000001")
    }

    func testSetModeMatchesRFC() {
        XCTAssertEqual(ClientMessage.setMode(1).hex, "0a000001") // RFC §5.7
    }

    func testScaleFactorMatchesRFC() {
        XCTAssertEqual(ClientMessage.scaleFactor(1.0).hex, "08003ff0000000000000") // RFC §8.10
    }

    func testSetDisplayMatchesRFC() {
        XCTAssertEqual(ClientMessage.setDisplay(combineAll: true).hex, "0d010000" + "00000000") // RFC §7.4
    }

    func testClientCutTextMatchesRFC6143() {
        // RFC 6143 §7.5.6: u8 6, 3 pad, u32 length, Latin-1 text
        XCTAssertEqual(ClientMessage.clientCutText("hé").hex, "06000000" + "00000002" + "68e9")
        XCTAssertEqual(ClientMessage.clientCutText("a👋").hex, "06000000" + "00000002" + "613f",
                       "non-Latin-1 characters are replaced with '?'")
    }

    func testPointerEventClamps() {
        XCTAssertEqual(ClientMessage.pointerEvent(buttons: 0x1ff, x: -5, y: 70000).hex, "05ff0000ffff")
    }

    func testStaticDisplayConfigurationClearsDynamicFields() {
        let dyn = ClientMessage.setDisplayConfiguration(logicalWidth: 1376, logicalHeight: 1032)
        let stat = ClientMessage.setDisplayConfiguration(logicalWidth: 1376, logicalHeight: 1032, dynamic: false)
        XCTAssertEqual(dyn.count, stat.count)
        let d = 0x0c   // descriptor start
        XCTAssertEqual(Data(dyn[d + 0x7a..<d + 0x82]).hex, "0000000100000004")
        XCTAssertEqual(Data(stat[d + 0x7a..<d + 0x82]).hex, "0000000000000000")
        XCTAssertEqual(Data(stat[d + 0x96..<d + 0x9a]).hex, "00000000")
    }
}
